/**
 * ───────────────────────────────────────────────────────────────────────────────
 * [shadcn registry item · 教学演示件] AI 流式表格 AI Streaming Table
 *
 * 来源:uiux-atlas src/content/entries/components/ai-streaming-table/demo/Demo.tsx
 *       (由 scripts/generate-registry.mjs 内联生成;源文件保持不动,重跑生成器即刷新)
 *
 * 诚实标注:这是教学演示件,不是生产组件。原 demo 依赖的三个 @/ 内部模块
 * (@/lib/store 参数 store、@/lib/types 类型、@/components/DemoStage 演示舞台)
 * 在 registry 消费端不可用,已原位改写为「[registry 改写]」注释;文件体内对应的
 * getEntryStore / EntrySchema / DemoStage 引用需按各注释提示替换后,本文件才可编译运行。
 * 它记录的是「本站条目页如何实时驱动参数」,供阅读与改写,不可直接安装即用。
 *
 * 依赖:仅 react(+宿主的 react-dom 渲染);registry item 的 dependencies 留空,
 * 由消费端项目按自身版本声明 react。
 * ───────────────────────────────────────────────────────────────────────────────
 */
import { useEffect, useMemo, useState } from "react";
// [registry 改写] 原:import { getEntryStore } from "@/lib/store"; —— 本站内部参数 store(getEntryStore,演示页参数面板 → 舞台的实时数据源),registry 消费端不可用;接入时请改为本地受控 state(useState + props),文件体内的 getEntryStore / store.get / store.subscribe 调用需同步替换。
// [registry 改写] 原:import type { EntrySchema } from "@/lib/types"; —— 本站条目 schema 的 TS 类型(EntrySchema),registry 消费端不可用;接入时请以你自己的参数定义类型内联替代,文件体内的 EntrySchema 注解需同步替换。
// [registry 改写] 原:import DemoStage from "@/components/DemoStage"; —— 本站演示舞台组件(.demo-stage:cssVar 注入点 + 舞台铭牌 + #s= 分享参数恢复),registry 消费端不可用;接入时请以自有舞台容器(如一个 <div>)替代,文件体内的 <DemoStage> 标签需同步替换。

interface DemoProps {
  entryId: string;
  schema: EntrySchema;
}

/* 数据行脚本:8 行 × 3 列,行间隔 450ms 模拟 token 流(总时长 ≈ 3.6s)。
   列宽声明挂在表头(fixed),数据未到的行由骨架占位(同高,零位移换载)。 */
const ROWS: { zh: string; en: string; q3: string; q4: string }[] = [
  { zh: "流式吞吐 tokens/s", en: "Stream throughput tokens/s", q3: "38", q4: "52" },
  { zh: "首块延迟 TTFT", en: "First-token latency TTFT", q3: "410ms", q4: "360ms" },
  { zh: "块级 memo 命中", en: "Block-memo hit rate", q3: "87%", q4: "91%" },
  { zh: "锁底打断次数", en: "Sticky-bottom interrupts", q3: "0.4/轮", q4: "0.2/轮" },
  { zh: "表格行重渲次数", en: "Table row re-renders", q3: "1.2/行", q4: "1.0/行" },
  { zh: "骨架换载位移", en: "Skeleton swap shift", q3: "0px", q4: "0px" },
  { zh: "表内滚动触发", en: "In-table scroll engaged", q3: "18%", q4: "26%" },
  { zh: "reduced-motion 回退", en: "Reduced-motion fallback", q3: "正常", q4: "正常" },
];

type Phase = "streaming" | "done";

const css = `
.stm-wrap { width: min(560px, calc(100% - 24px)); position: relative; }
.stm-scroll {
  max-height: var(--stm-max-h, 260px);
  overflow: auto;
  scrollbar-width: thin;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-elev);
}
.stm-tbl {
  table-layout: fixed;
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
  color: var(--text-1);
}
.stm-tbl caption {
  text-align: left;
  font-size: 12px;
  color: var(--text-faint);
  padding: 8px 12px 4px;
}
.stm-tbl th, .stm-tbl td {
  border-bottom: 1px solid var(--border);
  padding: 7px 12px;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.stm-tbl thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--bg-elev);
  font-weight: 600;
  font-size: 12px;
  color: var(--text-dim, var(--text-1));
}
.stm-tbl th:first-child { width: 40%; }
.stm-tbl td.num { text-align: right; font-variant-numeric: tabular-nums; }
.stm-tbl tbody tr { animation: stm-row var(--stm-row-ms, 250ms) ease both; }
@keyframes stm-row { from { opacity: 0; } to { opacity: 1; } }
/* 骨架格:与真实行同高的 shimmer 占位(完成换载零位移) */
.stm-skel td {
  background-image: linear-gradient(90deg, transparent 30%, color-mix(in srgb, var(--text-1) 9%, transparent) 50%, transparent 70%);
  background-size: 200% 100%;
  animation: stm-sweep 1.4s linear infinite;
  color: transparent;
}
.stm-skel td[data-ph="dash"]::after {
  content: "—";
  color: var(--text-faint);
  background: none;
  animation: none;
}
@keyframes stm-sweep { from { background-position: 100% 0; } to { background-position: -100% 0; } }
.stm-status { margin: 8px 2px 0; font-size: 12px; color: var(--text-faint); }
.stm-tools { position: absolute; right: -4px; top: -38px; display: flex; gap: 6px; }
.stm-tools button {
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit;
  font-size: 12px;
  padding: 4px 12px;
  cursor: pointer;
}
.stm-tools button:hover { border-color: var(--accent); color: var(--accent); }
.stm-tools button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.stm-hint { margin: 8px 2px 0; font-size: 12px; color: var(--text-faint); }
@media (prefers-reduced-motion: reduce) {
  .stm-tbl tbody tr, .stm-skel td { animation: none; }
  .stm-skel td { color: var(--text-faint); }
}
`;

/**
 * AI 流式表格演示:表头先渲染锁宽 → 骨架行占位 → 数据行随流逐行淡入替换骨架 →
 * 完成后可选切 auto 精修。tableLayout / skeletonRows / autoLayoutOnComplete /
 * emptyCellPlaceholder 为 JS 型参数(订阅 store);rowRevealMs(--stm-row-ms)与
 * maxBodyHeight(--stm-max-h)为 CSS 变量型参数(经 DemoStage 注入)。
 * 表内滚动(8 行 × maxBodyHeight 默认 260px)不撑破外层视口。
 */
export default function Demo({ entryId, schema }: DemoProps) {
  const store = getEntryStore(entryId, schema);
  const [tableLayout, setTableLayout] = useState(() => store.get("tableLayout") as string);
  const [skeletonRows, setSkeletonRows] = useState(() => store.get("skeletonRows") as number);
  const [autoLayoutOnComplete, setAutoLayoutOnComplete] = useState(() => store.get("autoLayoutOnComplete") as string);
  const [placeholder, setPlaceholder] = useState(() => store.get("emptyCellPlaceholder") as string);

  const [runId, setRunId] = useState(0);
  const [arrived, setArrived] = useState(0);

  useEffect(
    () =>
      store.subscribe(() => {
        setTableLayout(store.get("tableLayout") as string);
        setSkeletonRows(store.get("skeletonRows") as number);
        setAutoLayoutOnComplete(store.get("autoLayoutOnComplete") as string);
        setPlaceholder(store.get("emptyCellPlaceholder") as string);
      }),
    [store],
  );

  const replay = () => {
    setRunId((n) => n + 1);
    setArrived(0);
  };

  // 行级渐进:每 450ms 一行到达(块级 memo 语义——已到达行不重渲,demo 以 slice 静态渲染)
  useEffect(() => {
    if (arrived >= ROWS.length) return;
    const id = window.setTimeout(() => setArrived((n) => n + 1), arrived === 0 ? 400 : 450);
    return () => window.clearTimeout(id);
  }, [runId, arrived]);

  const phase: Phase = arrived >= ROWS.length ? "done" : "streaming";
  const fixed = tableLayout === "fixed-skeleton" || (phase === "streaming" ? true : autoLayoutOnComplete !== "on");
  const skeletonCount = phase === "streaming" ? skeletonRows : 0;
  const rows = useMemo(() => ROWS.slice(0, arrived), [arrived]);

  return (
    <DemoStage entryId={entryId} schema={schema}>
      <div className="stm-wrap">
        <div className="stm-tools" role="group" aria-label="演示控制 Demo controls">
          <button type="button" onClick={replay}>重播 Replay</button>
        </div>
        <div className="stm-scroll" tabIndex={0} role="region" aria-label="流式表格 Streaming table" aria-busy={phase === "streaming" ? "true" : "false"}>
          <table
            className="stm-tbl"
            style={fixed ? { tableLayout: "fixed" } : { tableLayout: "auto" }}
          >
            <caption>季度流式指标 Quarterly streaming metrics(AI 回答中流式生成的表格 A table streamed inside an answer)</caption>
            <thead>
              <tr>
                <th scope="col">指标 Metric</th>
                <th scope="col" style={{ textAlign: "right" }}>Q3</th>
                <th scope="col" style={{ textAlign: "right" }}>Q4</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.en}>
                  <td>{r.zh} {r.en}</td>
                  <td className="num">{r.q3}</td>
                  <td className="num">{r.q4}</td>
                </tr>
              ))}
              {Array.from({ length: skeletonCount }, (_, i) => (
                <tr className="stm-skel" key={`skel-${i}`} aria-hidden="true">
                  <td data-ph={placeholder === "dash" ? "dash" : undefined}>▒▒▒▒▒</td>
                  <td data-ph={placeholder === "dash" ? "dash" : undefined}>▒▒▒</td>
                  <td data-ph={placeholder === "dash" ? "dash" : undefined}>▒▒</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p className="stm-status" aria-live="polite">
          {phase === "streaming"
            ? `生长中 Growing… 已到 ${arrived}/${ROWS.length} 行 rows · 布局 layout: ${fixed ? "fixed(列宽锁定 widths locked)" : "auto(收尾精修 closing pass)"}`
            : `已完成 Done · ${ROWS.length} 行 rows · ${autoLayoutOnComplete === "on" ? "已切 auto 精修 switched to auto-fit" : "保持 fixed kept fixed"}`}
        </p>
        <p className="stm-hint">
          行超出高度切表内滚动(sticky 表头),骨架行与真实行同高零位移 · Rows past the height scroll inside (sticky header); skeleton rows match real heights for zero-shift swaps
        </p>
      </div>
      <style>{css}</style>
    </DemoStage>
  );
}
